NAME = 'GerAlbrecht: German Albrecht Neues Testament und Psalmen'
BOOK = 'James'

CHAPTERS = {
    1: {
        1: 'Jakobus, ein Knecht Gottes und des Herrn Jesus Christus, entbietet den zwölf Stämmen in der Zerstreuung seinen Gruß.',
        2: 'Seid hocherfreut, meine Brüder, wenn ihr in allerlei Anfechtungen fallt!',
        3: 'Ihr wißt ja, daß die Prüfung eures Glaubens Beharrlichkeit zur Folge hat.',
        4: 'Und diese Beharrlichkeit sollt ihr in all euerm Handeln betätigen, damit ihr zur vollen geistlichen Reife kommt und es euch an keiner Tugend mangele.',
        5: 'Fehlt es aber einem von euch an Weisheit, der bitte Gott darum, und dann wird sie ihm gegeben werden; denn Gott gibt allen gern und hält es nachher niemand vor.',
        6: 'Er bitte aber im Glauben, ohne zu zweifeln. Denn der Zweifler gleicht einer Meereswoge, die vom Sturm getrieben und geschaukelt wird.',
        7: 'Ein solcher Mensch darf nicht erwarten, etwas von dem Herrn zu empfangen.',
        8: 'Er hat gleichsam zwei Seelen in seiner Brust und schwankt ohne inneren Halt auf allen seinen Wegen hin und her.',
        9: 'Der arme, geringe Bruder rühme sich seiner (künftigen) Erhöhung,',
        10: 'der reiche dagegen denke an seine Erniedrigung; denn wie des Grases Blume wird er vergehen.',
        11: 'Die Sonne geht auf mit ihrer Glut und versengt das Gras; dann fällt seine Blume ab, und ihre Schönheit ist dahin. So wird auch der Reiche in all seinem Treiben verwelken.',
        12: 'Heil dem Mann, der in Anfechtung ausharrt! Denn hat er sich bewährt, dann soll er das (ewige) Leben empfangen als Siegeskranz, den der Herr verheißen hat denen, die ihn lieben.',
        13: 'Keiner, der versucht wird, behaupte: "Ich werde von Gott versucht." Denn Gott, dem alles Böse fremd ist, versucht niemand (zum Bösen).',
        14: 'Sondern ein jeder wird versucht, indem er von seiner eigenen Lust (zum Bösen) gereizt und verlockt wird.',
        15: 'Wenn dann die Lust empfangen hat, so gebiert sie die Sünde. Ist aber die Sünde völlig ausgereift, so gebiert sie den Tod.',
        16: 'Laßt euch also nicht täuschen, meine geliebten Brüder!',
        17: "Jede vortreffliche Gabe und jede vollkommene Schenkung kommt von oben herab, von dem Vater der Lichter. Bei ihm gibt's keine Veränderung, keinen Wechsel von Licht und Schatten.",
        18: 'Er hat uns nach dem Ratschluß seines Willens durch das Wort der Wahrheit gezeugt, damit wir gleichsam eine Erstlingsschar unter seinen Geschöpfen wären.',
        19: 'Das wißt ihr, meine geliebten Brüder. Darum sei jeder schnell bereit zum Hören, langsam zum Reden, (und namentlich) langsam zum Zorn.',
        20: 'Denn ein zorniger Mensch tut nicht, was Gott gefällt.',
        21: 'So trennt euch nun von allem unsauberen Wesen und dem letzten Überrest der Bosheit und nehmt das Wort, das euch eingepflanzt werden soll, mit Sanftmut auf! Denn es hat die Kraft, eure Seelen zu erretten.',
        22: 'Werdet Täter des Wortes und beschränkt euch nicht aufs Hören: sonst betrügt ihr euch selbst!',
        23: 'Denn wer nur ein Hörer des Wortes ist, aber kein Täter, der gleicht dem Mann, der sein Äußeres im Spiegel beschaut.',
        24: 'Er betrachtet sich wohl, aber er geht weg und vergißt sofort wieder, wie er ausgesehen hat.',
        25: 'Wer aber beharrlich in das vollkommene Gesetz der Freiheit blickt und dabei nicht ein vergeßlicher Hörer, sondern ein wirklicher Täter ist, ein solcher Mensch wird sich glücklich fühlen bei seinem Tun.',
        26: 'Meint einer, er diene Gott, und hält dabei seine Zunge nicht im Zaum, sondern betrügt sein Herz, des Gottesdienst hat keinen Wert.',
        27: 'Ein in Gottes, des Vaters, Augen reiner und fleckenloser Gottesdienst ist es, wenn man Witwen und Waisen in ihrer Trübsal besucht und sich von der Welt unbefleckt bewahrt.',
    },
    2: {
        1: 'Meine Brüder, seid frei von Menschengefälligkeit, wenn ihr wirklich den Glauben habt, den unser Herr Jesus Christus, der zur Herrlichkeit erhoben ist, bewiesen hat und wirkt.',
        2: 'Da tritt zum Beispiel in eure (gottesdienstliche) Versammlung ein Mann, geschmückt mit goldenem Ring und prächtigem Gewand, und ihm folgt ein Armer in unsauberem Kleid.',
        3: 'Staunt ihr nun den an, der das prächtige Gewand trägt, und sagt zu ihm: "Nimm du diesen Ehrenplatz!", während ihr zu dem Armen sprecht: "Du kannst dort stehen!" — oder auch: "Setze dich unten an meinen Fußschemel!" —,',
        4: 'kommt ihr da nicht mit euch selbst in Widerspruch und zeigt euch als Richter von verwerflicher Sinnesart?',
        5: 'Merkt auf, geliebte Brüder: Hat Gott nicht solche, die die Welt arm nennt, auserwählt, damit sie reich seien im Glauben und das Königreich ererben, das er denen verheißen hat, die ihn lieben?',
        6: 'Ihr aber habt den Armen verächtlich behandelt! Sind es nicht gerade die Reichen, die euch Gewalt antun und euch vor die Gerichte schleppen?',
        7: 'Sind sie es nicht, die den herrlichen Namen, nach dem ihr benannt worden seid, verlästern?',
        8: 'Gewiß, wenn ihr (ohne einen Unterschied zu machen) das königliche Gebot erfüllt, das zum Ausdruck kommt in dem Schriftwort: Du sollst deinen Nächsten lieben wie dich selbst, so tut ihr recht.',
        9: 'Handelt ihr aber nach Menschengunst, so tut ihr Sünde, und das Gesetz verurteilt euch als Übertreter.',
        10: 'Wer nämlich das ganze Gesetz erfüllt, aber gegen ein einziges Gebot verstößt, der hat damit alle Gebote übertreten.',
        11: 'Denn ganz derselbe, der gesagt hat: "Du sollst nicht ehebrechen!", hat auch gesprochen: "Du sollst nicht morden!" Bist du nun zwar kein Ehebrecher, aber ein Mörder, so bist du ein Gesetzesübertreter.',
        12: 'Denkt bei all euerm Reden und Handeln daran, daß ihr einst durch ein Gesetz der Freiheit gerichtet werden sollt.',
        13: 'Denn das Gericht trifft erbarmungslos den, der keine Barmherzigkeit geübt hat. Der Barmherzige dagegen braucht kein Gericht zu fürchten.',
        14: 'Was nützt es, meine Brüder, wenn einer behauptet, er habe Glauben, und kann dabei doch keine Werke aufweisen?',
        15: 'Kann ihn denn ein solcher Glaube retten? Denkt euch: Ein Bruder oder eine Schwester hat keine Kleidung, und es fehlt ihnen am täglichen Brot.',
        16: 'Spräche nun einer von euch zu ihnen: "Geht hin in Frieden, wärmt euch und eßt euch satt!", aber ihr gäbt ihnen nicht, was sie zum Leben nötig haben, — was nützt es ihnen?',
        17: "Ebenso ist's auch mit dem Glauben: hat er keine Werke aufzuweisen, dann ist er in sich selber tot.",
        18: 'Man könnte nun (jemand, der sich auf einen Glauben ohne Werke verläßt) dies erwidern: "Du hast Glauben (wie du sagst), und ich habe (neben dem Glauben auch noch) Werke aufzuweisen. Zeig mir deinen Glauben, der ohne Werke ist, dann will ich dir aus meinen Werken meinen Glauben zeigen!',
        19: 'Du glaubst: es gibt nur einen Gott? Sehr schön! Aber das glauben auch die bösen Geister, und trotzdem zittern sie.',
        20: 'Willst du gedankenloser Mensch nun einsehen, daß ein Glaube ohne Werke nutzlos ist, (so frage dich:)',
        21: 'Ist unser Vater Abraham nicht durch Werke gerechtfertigt worden? Er hat ja seinen Sohn Isaak auf dem Opferaltar dargebracht.',
        22: 'Da siehst du: sein Glaube ging mit seinen Werken Hand in Hand, und erst durch seine Werke ist sein Glaube vollkommen geworden.',
        23: 'So hat sich das Schriftwort erfüllt: Abraham glaubte Gott, und das ward ihm zur Gerechtigkeit gerechnet, und er wurde Gottes Freund genannt."',
        24: 'Ihr seht also: der Mensch wird durch Werke gerechtfertigt, und nicht durch Glauben allein.',
        25: 'Ist nicht ebenso auch die Dirne Rahab durch Werke gerechtfertigt worden? Sie hat ja die Kundschafter bei sich aufgenommen und sie nachher auf einem anderen Weg entkommen lassen.',
        26: 'Geradeso wie der Leib ohne Geist tot ist, ebenso ist auch der Glaube ohne Werke tot.',
    },
    3: {
        1: 'Tretet nicht so zahlreich als Lehrer auf, meine Brüder, und bedenkt, daß wir (Lehrer) eine größere Verantwortung haben (als andere)!',
        2: 'Wir alle fehlen ja in vielen Stücken. Wer sich beim Reden nicht versündigt, der ist ein geistlich reifer Mann und vermag (außer der Zunge) auch den ganzen Leib im Zaum zu halten.',
        3: 'Legen wir den Pferden, um sie uns gehorsam zu machen, die Zügel ins Maul, so lenken wir dadurch auch ihren ganzen Leib.',
        4: 'Ja die größten und von heftigen Winden bewegten Schiffe lenkt der Steuermann mit einem ganz kleinen Ruder, wohin er will.',
        5: 'So ist auch die Zunge nur ein kleines Glied; und wie großprahlerisch tritt sie auf! Welch großen Wald vermag ein kleines Feuer anzuzünden!',
        6: "Auch die Zunge ist ein Feuer. Die Zunge gibt sich her zum Schmuck der Gerechtigkeit. Sie ist's, die unseren Gliedern den ganzen Leib befleckt und sogar den Weltkreis in Flammen setzt, während sie selbst von der Hölle entzündet wird.",
        7: 'Die Kraft aller möglichen Geschöpfe — der vierfüßigen Tiere und Vögel, der Schlangen und der Fische — kann der Mensch mit seiner Kraft zähmen und hat sie auch gezähmt.',
        8: 'Die Zunge aber vermag kein Mensch zu zähmen: sie ist ein unstetes Übel, voll tödlichen Giftes.',
        9: 'Mit ihr preisen wir den Herrn und Vater, und mit ihr fluchen wir den Menschen, die doch nach Gottes Bild geschaffen sind.',
        10: 'So gehen aus demselben Mund Segen und Fluch hervor. Das, meine Brüder, sollte nicht so sein.',
        11: 'Läßt denn eine Quelle aus derselben Mündung süßes und bitteres Wasser sprudeln?',
        12: 'Kann ein Feigenbaum, meine Brüder, Oliven tragen oder ein Weinstock Feigen? Ebensowenig kann eine Salzquelle süßes Wasser geben.',
        13: 'Wer unter euch ist weise und verständig? Der zeige durch seinen guten Wandel und handle in jener Sanftmut, die aus der Weisheit fließt!',
        14: 'Habt ihr aber bitteren Neid und Zank in euerm Herzen, so rühmt euch nur nicht (eurer Weisheit)! Denn das widerspräche der Wahrheit, und ihr würdet als Lügner erfunden.',
        15: 'Solche Weisheit kommt wahrlich nicht von oben; nein, sie ist irdisch, böse, ja teuflisch.',
        16: 'Denn wo Neid und Hader herrschen, da finden sich auch Unordnung und alle möglichen schlimmen Händel.',
        17: 'Die Weisheit aber, die von oben stammt, ist vor allem lauter, dann friedfertig, nachgiebig, folgsam, voll Erbarmen und reich an guten Früchten, frei von Argwohn und Heuchelei.',
        18: 'Der Same, der die Frucht der Gerechtigkeit hervorbringt, wird von denen, die Frieden stiften, mit friedfertigem Sinn ausgestreut.',
    },
    4: {
        1: 'Woher kommen die Kämpfe und Streitigkeiten (über mein und dein) unter euch? Kommen sie nicht aus euern (auf irdischen Reichtum gerichteten) Lüsten, die in euern Gliedern (mit euerm besseren Ich) im Streit sind?',
        2: 'Ihr seid begehrlich (nach den Gütern dieser Welt) und bekommt sie doch nicht. Ihr haßt und neidet einander bis auf den Tod, aber damit erreicht ihr eure Wünsche nicht. Ihr lebt in offenem Kampf und Krieg und erlangt doch nichts, weil ihr nicht betet.',
        3: 'Oder: ihr betet und empfangt doch nichts, weil ihr in böser Absicht betet: ihr wollt ja (die irdischen Güter, um die ihr bittet) in euern Lüsten vergeuden.',
        4: 'Ihr treulosen Gemeinden, die ihr den Bund mit Gott gebrochen habt, wißt ihr denn nicht, daß die Freundschaft mit der Welt Feindschaft ist gegen Gott? Wer also der Welt Freund sein will, der macht sich zu Gottes Feind.',
        5: 'Oder meint ihr, die Worte der Schrift hätten nichts zu bedeuten? Der Geist, den er in uns hat Wohnung nehmen lassen, begehrt eifersüchtig (unser ganzes Herz).',
        6: 'Um so größer aber ist die Gnade, die er gibt. Deshalb heißt es: Gott widersteht den Hoffärtigen, aber den Demütigen gibt er Gnade.',
        7: 'Darum unterwerft euch Gott (in Demut)! Widersteht dem Teufel, so wird er von euch fliehen!',
        8: 'Naht euch Gott, so wird er sich euch nahen! Reinigt eure Hände, ihr Sünder, und heiligt eure Herzen, ihr Unentschiedenen!',
        9: 'Fühlt euer Elend und trauert mit Tränen! Euer Lachen wandle sich in Leid und eure Freude in Betrübnis!',
        10: 'Ja demütigt euch vor dem Herrn, so wird er euch erhöhen!',
        11: 'Redet einander nichts Böses nach, ihr Brüder! Wer seinem Bruder Böses nachredet oder seinen Bruder richtet, der mißbraucht das Gesetz und stellt sich über das Gesetz. Stellst du dich aber über das Gesetz, so bist du nicht ein Täter des Gesetzes, sondern du wirfst dich zum Richter auf.',
        12: 'Doch nur einer ist Gesetzgeber und Richter: er, der die Macht hat, zu erretten und zu verderben. Wie kommst du aber dazu, über deinen Nächsten zu Gericht zu sitzen?',
        13: 'Jetzt ein Wort an euch, die ihr sagt: "Heute oder morgen wollen wir in die und die Stadt gehen, dort ein Jahr bleiben, Geschäfte machen und Geld verdienen"',
        14: '- und ihr wißt nicht einmal, was der morgende Tag bringt. Was ist denn euer Leben? Nur ein Dunst, der eine Weile sichtbar ist und dann verschwindet. —',
        15: 'Statt dessen solltet ihr sagen: "Wenn es des Herrn Wille ist, so werden wir leben und dies oder jenes tun."',
        16: 'Nun aber prahlt ihr mit euern guten Tagen. All dies Prahlen ist verwerflich.',
        17: 'Wer nun das Gute kennt, das er zu tun hat, und es unterläßt, dem wird es als Sünde angerechnet.',
    },
    5: {
        1: 'Jetzt ein Wort an euch, ihr Reichen: Weint und wehklagt ob der Leiden, die über euch kommen sollen!',
        2: 'Euer Reichtum ist vermodert, und eure Kleider sind von Motten zernagt.',
        3: 'Euer Gold und Silber ist mit Rost überzogen, und ihr Rost wird euch ein Zeugnis sein und euer Fleisch verzehren wie Feuer. Ihr habt Schätze aufgehäuft — noch dazu in den letzten Tagen!',
        4: 'Aber der Lohn, um den ihr die Arbeiter, die eure Felder gemäht, betrogen habt, der schreit (zum Himmel), und die Klagerufe der Schnitter sind zu den Ohren des Herrn der Heerscharen gedrungen.',
        5: 'Ihr habt auf Erden geschwelgt und gepraßt; wie Tiere am Schlachttag seid ihr nach Genüssen gierig gewesen.',
        6: 'Verurteilt und hingemordet habt ihr den Gerechten, der eurer Willkür wehrlos preisgegeben war!',
        7: 'Harrt denn geduldig aus, ihr Brüder, bis auf die Wiederkunft des Herrn! Ihr wißt: der Landmann wartet auf die köstliche Frucht der Erde und harrt in Geduld, bis sie Herbstregen und Frühlingsregen empfängt.',
        8: 'So harrt auch ihr in Geduld, stärkt eure Herzen; denn die Wiederkunft des Herrn ist nahe!',
        9: 'Seufzt nicht widereinander, Brüder, damit ihr nicht gerichtet werdet (wegen eurer Ungeduld)! Bedenkt: der Richter steht schon vor der Tür!',
        10: 'Zum Vorbild im Leiden und in der Geduld nehmt euch, Brüder, die Propheten, die im Namen des Herrn geredet hatten!',
        11: 'Die Dulder preisen wir selig. Wie Hiob geduldig ausharrte, das habt ihr vernommen, und aus dem (herrlichen) Ende, das der Herr (seinen Leiden) bereitet hat, erkennt man deutlich, daß der Herr reich ist an Mitleid und Erbarmen.',
        12: 'Vor allem, meine Brüder, schwört nicht, weder bei dem Himmel noch bei der Erde noch mit irgendeinem anderen Schwur! Euer Ja sei einfach Ja, und euer Nein sei einfach Nein, damit ihr nicht (durch leichtfertiges Schwören) einem (göttlichen) Gericht verfallt!',
        13: 'Ist jemand unter euch bekümmert, der bete! Ist einer frohes Mutes, der singe Loblieder!',
        14: 'Ist jemand unter euch krank, der lasse die Ältesten der Gemeinde rufen! Die sollen dann über ihn beten und ihn mit Öl salben in dem Namen des Herrn.',
        15: 'Das im Glauben dargebrachte Gebet wird den Kranken erretten, und der Herr wird ihn aufrichten (von seiner Krankheit). Und hat er Sünden begangen, so sollen sie ihm vergeben werden.',
        16: 'So bekennt denn einander eure Sünden und betet füreinander, damit ihr Heilung findet! Denn das inständige Gebet eines Gerechten hat große Kraft.',
        17: 'Elia war ein Mensch ganz ebenso wie wir, und er betete ernstlich, es möge nicht regnen. Und wirklich, es regnete drei Jahre und sechs Monate nicht auf Erden.',
        18: 'Dann betete er abermals. Da gab der Himmel wieder Regen, und die Erde brachte ihre Frucht hervor.',
        19: 'Meine Brüder, irrt einer unter euch von dem Weg der Wahrheit ab, und es führt ihn jemand wieder zurück,',
        20: 'so wißt: Wer einen Sünder von seinem Irrweg zurückbringt, der rettet des Sünders Seele vom Tod und gewinnt ihm Vergebung für viele Sünden.',
    },
}
